import{_ as e}from"./chunks/connect.BTLErx-Y.js";import{_ as t,o as i,c as l,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Подключение и вход","description":"","frontmatter":{"pageId":"players/connect","contentRevision":2},"headers":[],"relativePath":"ru/players/connect.md","filePath":"ru/players/connect.md"}'),r={name:"ru/players/connect.md"};function n(s,a,p,c,h,d){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="подключение-и-вход" tabindex="-1">Подключение и вход <a class="header-anchor" href="#подключение-и-вход" aria-label="Permalink to &quot;Подключение и вход&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><img class="wiki-art" src="'+e+'" alt="Две колонии подключаются к серверу по защищённому соединению." width="960" height="440"><p class="wiki-caption">Две колонии подключаются к серверу по защищённому соединению.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol class="flow-diagram" aria-label="Схема процесса"><li><strong>Адрес и TLS</strong><span>Сверь сервер и отпечаток.</span></li><li><strong>Личный вход</strong><span>Steam или разрешённый парольный аккаунт.</span></li><li><strong>Сборка</strong><span>Diff → разрешённая установка → restart → сверка.</span></li><li><strong>Колония</strong><span>Текущий серверный сейв либо новая колония.</span></li></ol><p>В меню <strong>Мультиплеер</strong> добавь host и порт (по умолчанию 25560). Адрес выдаёт администратор; браузерный URL панели и игровой endpoint не обязательно одинаковы. Если сервер защищён общим паролем, он нужен дополнительно к личному входу.</p><p>Steam-вход использует билет Steam. Парольный вход доступен только когда сервер разрешил его; логин и пароль относятся к этому серверу. Новый сертификат запомнится после доверия. При изменении pin сначала спроси администратора, действительно ли сертификат заменён.</p><p>После входа сервер либо загружает сохранённую колонию, либо предлагает создать новую, либо показывает различия набора модов. Исправь указанные различия и подключись снова.</p><h2 id="login-flow" tabindex="-1">Вход по шагам: сертификат, учётная запись, колония <a class="header-anchor" href="#login-flow" aria-label="Permalink to &quot;Вход по шагам: сертификат, учётная запись, колония {#login-flow}&quot;">​</a></h2><ol><li>Открой сохранённый сервер либо добавь точные host/port. URL браузерной панели может отличаться от игрового адреса.</li><li>При первом TLS-подключении сравни отпечаток с сообщением администратора по другому каналу. Сохраняй доверие только после сверки. Изменённый pin — отдельная остановка, не обычная кнопка «продолжить».</li><li>Введи общий пароль сервера, если он включён. Он не заменяет Steam-ticket или личный пароль.</li><li>Для Steam дождись результата проверки билета; временный отказ может автоматически повторяться. Для парольного входа используй учётную запись именно этого сервера. Администратор должен разрешить этот метод.</li><li>Пройди сверку сборки. Далее сервер либо загружает текущую колонию, либо предлагает новую. Если ожидаешь старую — прежде создания проверь аккаунт и адрес.</li></ol><p><strong>Успех:</strong> загружена домашняя карта, соединение активно, нет незавершённого восстановления. Имя в публичном списке и логин учётной записи — не взаимозаменяемые значения.</p><h2 id="login-refusal" tabindex="-1">Различай временное ожидание и окончательный отказ <a class="header-anchor" href="#login-refusal" aria-label="Permalink to &quot;Различай временное ожидание и окончательный отказ {#login-refusal}&quot;">​</a></h2><p>«Waiting for Steam to accept the login» означает ожидание Steam, не повреждение сейва. «login details are invalid» требует проверки данных. «This account logged in from another place» останавливает эту копию: не продолжай её как независимую временную линию.</p><p>При обычном обрыве игра ставит паузу и переподключается: сначала через секунду, затем реже, максимум раз в минуту. Через две минуты можно выбрать ожидание или меню; попытки продолжаются за окном. Окончательный отказ (например, бан или неподтверждённый новый сертификат) требует возвращения в меню и устранения причины. Сохрани локальные данные, не заменяй их другой колонией.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не отключай TLS ради устранения ошибки сертификата. Не передавай личные пароли через чат. При временном отказе Steam дождись повторной проверки, не создавай много новых аккаунтов.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./modpacks">Набор модов сервера</a></li><li><a href="./../admins/security-auth">TLS, вход и права</a></li><li><a href="./troubleshooting">Проблемы игрока</a></li></ul>',19)])])}const f=t(r,[["render",n]]);export{u as __pageData,f as default};
